import {Voyage,launchVector,clamp,LEVELS} from './model.mjs?v=1.0.0';
import {PALETTES} from './levels.mjs?v=1.0.0';
import {Inkscape} from './render.mjs?v=1.0.0';
import {SeaAudio} from './audio.mjs?v=1.0.0';
import {Logbook} from './storage.mjs?v=1.0.0';
const $=s=>document.querySelector(s),canvas=$('#sea'),panel=$('#panel'),content=$('#panelContent');
let local;try{local=window.localStorage;}catch{}
const book=new Logbook(local);try{if(!local?.getItem?.('margin-tide-v1')&&matchMedia('(prefers-reduced-motion: reduce)').matches)book.data.settings.motion=false;}catch{}
const audio=new SeaAudio();audio.setEnabled(book.data.settings.audio);const game=new Voyage(book.data.last);
let art=null;let artFailed=false;
try{art=await new Promise((resolve,reject)=>{const im=new Image(),timeout=setTimeout(()=>reject(Error('art timeout')),10000);im.onload=()=>{clearTimeout(timeout);resolve(im);};im.onerror=()=>{clearTimeout(timeout);reject(Error('art unavailable'));};im.src='./assets/ink-atlas.webp';});}catch{artFailed=true;}
const renderer=new Inkscape(canvas,art);let mode='title',paused=false,drag=null,pointer=null,panelKind='',panelBack='',last=performance.now(),accumulator=0,toastTime=0,clearDelay=-1,lastHud='',hintsTime=0;const keys=new Set();let lastDirection={x:1,y:0};
function viewport(){const rect=$('#app').getBoundingClientRect(),style=getComputedStyle($('#gameUI'));renderer.insets={top:parseFloat(style.paddingTop)||0,bottom:parseFloat(style.paddingBottom)||0,left:parseFloat(style.paddingLeft)||0,right:parseFloat(style.paddingRight)||0};renderer.resize(rect.width,rect.height,window.devicePixelRatio||1);cancelAim();}
window.addEventListener('resize',viewport);window.visualViewport?.addEventListener('resize',viewport);viewport();
function palette(){return mode==='title'?PALETTES.paper:PALETTES[game.level.palette];}
function applyPalette(){const p=palette();for(const key of ['paper','ink','muted','line','gold'])document.documentElement.style.setProperty('--'+key,p[key]);document.querySelector('meta[name="theme-color"]').content=p.paper;}
function say(text,seconds=2.6){$('#toast').textContent=text;$('#toast').hidden=false;toastTime=seconds;$('#live').textContent=text;}
function save(){if(!book.save())say('このブラウザーでは記録を保存できません。航海は続けられます。',5);}
function cancelAim(){if(pointer!==null&&canvas.hasPointerCapture?.(pointer))try{canvas.releasePointerCapture(pointer);}catch{}pointer=null;drag=null;keys.clear();}
function hud(force=false){const stamp=[game.index,game.lightCount,game.shots,game.ready].join(':');if(stamp===lastHud&&!force)return;lastHud=stamp;$('#chapterNumber').textContent=String(game.index+1).padStart(2,'0');$('#chapterName').textContent=game.level.name;$('#chapterEnglish').textContent=game.level.en;
 $('#lamps').innerHTML=game.collected.map(v=>`<i class="lamp-symbol${v?' filled':''}" aria-hidden="true"></i>`).join('')+`<span class="lamp-number">${game.lightCount} / ${game.collected.length}</span>`;$('#lamps').setAttribute('aria-label',`灯 ${game.lightCount} / ${game.collected.length}`);$('#strokeCounter').innerHTML=`<strong>${String(game.shots).padStart(2,'0')}</strong> ひと漕ぎ`;
 canvas.setAttribute('aria-label',`${game.index+1}番目の海、${game.level.name}。灯 ${game.lightCount}/${game.collected.length}、${game.shots}漕ぎ。${game.ready?'港がひらいています。':'すべての灯を集めてください。'}`);
}
function start(index){cancelAim();clearDelay=-1;if(panel.open)panel.close();panelKind='';panelBack='';paused=false;game.load(index);mode='play';hintsTime=0;lastHud='';renderer.resetEffects();$('#title').hidden=true;$('#gameUI').hidden=false;$('#toast').hidden=true;$('#live').textContent='';toastTime=0;$('#firstGesture').hidden=book.data.best.some(Boolean)||index!==0;book.data.last=index;save();applyPalette();hud(true);audio.unlock();canvas.focus({preventScroll:true});}
function home(){cancelAim();clearDelay=-1;if(panel.open)panel.close();panelKind='';panelBack='';mode='title';paused=false;$('#title').hidden=false;$('#gameUI').hidden=true;$('#toast').hidden=true;updateTitle();applyPalette();}
function updateTitle(){const count=book.data.best.filter(Boolean).length;$('#beginText').textContent=count?'航海をつづける':'海へ出る';$('#continueNote').textContent=count?`${count} / 8 の海に灯がともっています。`:'八つの海を、ひとつずつ。';}
function switchHTML(key,label){return `<div class="panel-row"><span>${label}</span><button class="switch" data-setting="${key}" role="switch" aria-checked="${book.data.settings[key]}" aria-label="${label}"></button></div>`;}
function heading(kicker,title,close=true){return `<p class="panel-kicker">${kicker}</p><div class="panel-heading"><h2 id="panelTitle">${title}</h2>${close?'<button class="close-button" data-action="close" aria-label="閉じる">×</button>':''}</div>`;}
function showPanel(kind){cancelAim();paused=true;if(kind==='book'&&['clear','end'].includes(panelKind))panelBack=panelKind;panelKind=kind;let html='';
 if(kind==='pause')html=heading('A MOMENT ON THE WATER','ひとやすみ')+`<p class="panel-note">${String(game.index+1).padStart(2,'0')}　${game.level.name}<br>いまの航路は、このまま残っています。</p><button class="primary panel-primary" data-action="close"><span>海へ戻る</span><span>↗</span></button><div class="panel-links"><button class="text-button" data-action="retry">この海をやり直す ↺</button><button class="text-button" data-action="book">航海帖 ＋</button><button class="text-button" data-action="home">表紙へ</button></div><div class="panel-settings">${switchHTML('audio','音楽と効果音')}${switchHTML('motion','水面のゆらぎ')}</div>`;
 if(kind==='book')html=heading('EIGHT SEAS, ONE JOURNEY','航海帖')+`<div class="book-grid">${LEVELS.map((l,i)=>`<button class="chapter-tile" data-level="${i}" aria-label="${i+1} ${l.name}${book.data.best[i]?' 達成済み':''}"><span class="tile-number">${String(i+1).padStart(2,'0')}</span><span class="tile-name">${l.name}</span><span class="tile-marks">${book.data.best[i]?'✦'.repeat(book.data.best[i].medals)+'·'.repeat(3-book.data.best[i].medals):'—'}</span></button>`).join('')}</div><p class="book-caption">どの海からでも、旅を始められます。<br>✦ 到着　✦ 少ない漕ぎ数　✦ 墨に触れずに渡航</p>`;
 if(kind==='help')html=heading('A LITTLE GUIDE TO SAILING','風のつくり方')+`<div class="help-gesture"><svg viewBox="0 0 128 34" aria-hidden="true"><circle cx="17" cy="17" r="8"/><path stroke-dasharray="2 4" d="M28 17h48"/><path d="m66 11 9 6-9 6M91 17l29-8-10 8 10 8z"/></svg><span>引いて、放す。</span></div><ol class="help-list"><li>画面のどこからでも、進みたい方向と<br>逆に引いて、指を放します。</li><li>長く引くほど遠くへ。狙っている間は、<br>海の時間がゆっくりになります。</li><li>すべての灯を集めると港がひらきます。<br>墨に触れても、灯は失いません。</li></ol><button class="primary panel-primary" data-action="close"><span>わかった</span><span>↗</span></button><p class="help-keyboard">キーボード：方向キーで狙う・Spaceで漕ぐ。<br>Escapeで一時停止、Rでやり直し。</p>`;
 if(kind==='clear'||kind==='end'){const all=book.data.best.filter(Boolean).length;html=heading(kind==='end'?'A HARBOR OF LIGHT':'A PAGE IN YOUR LOGBOOK',kind==='end'?(all===8?'すべての海に、灯を。':'帰りの灯が、ともる。'):'航路が、つながった。',false)+`<div class="medals" aria-label="渡航のしるし ${game.medals()} / 3">${[0,1,2].map(i=>`<span class="${i<game.medals()?'':'empty'}" aria-hidden="true">✦</span>`).join('')}</div><div class="result-stats"><div><strong>${game.shots}</strong><small>ひと漕ぎ</small></div><div><strong>${game.lightCount}</strong><small>運んだ灯</small></div></div><p class="result-caption">${game.tears===0?'墨に触れず、きれいな航路が残りました。':'寄り道も、ひとつの航路。'}<br>${game.shots<=game.level.par?'少ない漕ぎ数のしるしがつきました。':`次の目安は ${game.level.par} 漕ぎ。何度でも旅を。`}</p><button class="primary panel-primary" data-action="${kind==='end'?'book':'next'}"><span>${kind==='end'?'航海帖をひらく':'次の海へ'}</span><span>↗</span></button><div class="panel-links"><button class="text-button" data-action="retry">もう一度、この海を ↺</button><button class="text-button" data-action="home">表紙へ</button></div>`;}
 panel.dataset.kind=kind;content.innerHTML=html;if(!panel.open)panel.showModal();content.querySelector('button')?.focus({preventScroll:true});
}
function closePanel(){if(panelKind==='clear'||panelKind==='end')return;if(panelBack){const back=panelBack;panelBack='';showPanel(back);return;}panel.close();paused=false;panelKind='';canvas.focus({preventScroll:true});}
panel.addEventListener('cancel',e=>{e.preventDefault();closePanel();});
content.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.level!==undefined){start(Number(button.dataset.level));return;}const setting=button.dataset.setting;if(setting){book.data.settings[setting]=!book.data.settings[setting];button.setAttribute('aria-checked',String(book.data.settings[setting]));if(setting==='audio'){audio.unlock();audio.setEnabled(book.data.settings.audio);updateAudioButton();}save();return;}
 switch(button.dataset.action){case'close':closePanel();break;case'next':start(game.index+1);break;case'retry':start(game.index);break;case'home':home();break;case'book':showPanel('book');break;}
});
$('#begin').addEventListener('click',()=>start(book.data.last));$('#logbook').addEventListener('click',()=>showPanel('book'));$('#how').addEventListener('click',()=>showPanel('help'));$('#chapterButton').addEventListener('click',()=>showPanel('book'));$('#pauseButton').addEventListener('click',()=>showPanel('pause'));$('#retryButton').addEventListener('click',()=>start(game.index));
function updateAudioButton(){const on=book.data.settings.audio;$('#audioButton').setAttribute('aria-pressed',String(on));$('#audioButton').setAttribute('aria-label',on?'音を消す':'音を出す');}
$('#audioButton').addEventListener('click',()=>{audio.unlock();book.data.settings.audio=!book.data.settings.audio;audio.setEnabled(book.data.settings.audio);updateAudioButton();save();});
canvas.addEventListener('pointerdown',e=>{if(mode!=='play'||paused||game.state!=='play'||game.respawn>0||pointer!==null||e.button>0)return;e.preventDefault();audio.unlock();pointer=e.pointerId;canvas.setPointerCapture(pointer);drag={sx:e.clientX,sy:e.clientY,ex:e.clientX,ey:e.clientY,vector:null};hintsTime=8;$('#firstGesture').hidden=true;},{passive:false});
canvas.addEventListener('pointermove',e=>{if(e.pointerId!==pointer||!drag)return;e.preventDefault();drag.ex=e.clientX;drag.ey=e.clientY;const a=renderer.worldPoint(drag.sx,drag.sy),b=renderer.worldPoint(drag.ex,drag.ey);drag.vector=launchVector(a.x-b.x,a.y-b.y);},{passive:false});
canvas.addEventListener('pointerup',e=>{if(e.pointerId!==pointer||!drag)return;e.preventDefault();const a=renderer.worldPoint(drag.sx,drag.sy),b=renderer.worldPoint(e.clientX,e.clientY);const vector=launchVector(a.x-b.x,a.y-b.y);if(vector)game.launch(vector);else say('進みたい方向と逆に、少し引いて放します。',2.5);cancelAim();},{passive:false});
canvas.addEventListener('pointercancel',()=>cancelAim());canvas.addEventListener('lostpointercapture',()=>{pointer=null;drag=null;});canvas.addEventListener('contextmenu',e=>e.preventDefault());
const arrowMap={ArrowRight:[1,0],KeyD:[1,0],ArrowLeft:[-1,0],KeyA:[-1,0],ArrowDown:[0,1],KeyS:[0,1],ArrowUp:[0,-1],KeyW:[0,-1]};
function keyboardAim(){let x=0,y=0;for(const key of keys){const p=arrowMap[key];if(p){x+=p[0];y+=p[1];}}if(x||y){const length=Math.hypot(x,y);lastDirection={x:x/length,y:y/length};return {vector:{x:lastDirection.x*780,y:lastDirection.y*780}};}return null;}
window.addEventListener('keydown',e=>{if(panel.open){if(e.code==='Escape'){e.preventDefault();closePanel();}return;}if(e.code==='Enter'&&mode==='title'){e.preventDefault();start(book.data.last);return;}if(mode!=='play')return;if(arrowMap[e.code]||['Space','Escape','KeyR'].includes(e.code))e.preventDefault();if(e.repeat)return;if(arrowMap[e.code])keys.add(e.code);if(e.code==='Space'){keyboardAim();audio.unlock();game.launch({x:lastDirection.x*780,y:lastDirection.y*780});$('#firstGesture').hidden=true;}if(e.code==='Escape')showPanel('pause');if(e.code==='KeyR')start(game.index);});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{cancelAim();if(mode==='play'&&game.state==='play'&&!panel.open)showPanel('pause');});
document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAim();audio.suspend();if(mode==='play'&&game.state==='play'&&!panel.open)showPanel('pause');}last=performance.now();accumulator=0;});
function processEvents(){for(const e of game.drain()){renderer.event(e,palette());audio.play(e);if(e.type==='light'){$('#live').textContent=`灯を集めました。${game.lightCount}/${game.collected.length}。`;}if(e.type==='open')say('灯がつながり、港がひらいた。',3);if(e.type==='tear')say('灯は失いません。さあ、もう一度。',2.1);if(e.type==='clear'){if(!book.finish(game.index,{shots:game.shots,tears:game.tears,medals:game.medals()}))say('記録を保存できませんでした。',4);cancelAim();clearDelay=1.15;$('#live').textContent=`${game.level.name}を渡りました。${game.shots}漕ぎ。`;}}}
function frame(now){const dt=Math.min(.08,Math.max(0,(now-last)/1000));last=now;if(!document.hidden){renderer.update(paused?0:dt);audio.update(dt,!paused);if(mode==='play'&&!paused){hintsTime+=dt;accumulator+=dt*(drag?.16:1);let ticks=0;while(accumulator>=1/120&&ticks++<14){game.step(1/120);accumulator-=1/120;}processEvents();hud();if(clearDelay>=0){clearDelay-=dt;if(clearDelay<=0){clearDelay=-1;showPanel(game.index===7?'end':'clear');}}$('#hint').textContent=drag?'狙いを決めて、指を放す。':game.respawn>0?'灯はそのまま。もう一度、海へ。':game.ready?'ひらいた港の輪へ、灯を届けよう。':hintsTime<7?game.level.note:'どこからでも引いて放す。航海の途中でも狙い直せます。';}else accumulator=0;if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('#toast').hidden=true;}
 renderer.draw(game,{mode,aim:paused?null:drag||keyboardAim(),motion:book.data.settings.motion});}requestAnimationFrame(frame);}
updateTitle();updateAudioButton();applyPalette();$('#begin').disabled=false;if(artFailed)say('墨の美術を読み込めませんでした。再読み込みで復元できます。',6);if(book.failed)say('記録を保存できない状態です。この画面では遊べます。',6);requestAnimationFrame(frame);
if('serviceWorker'in navigator&&location.protocol!=='file:'&&!['terminal.local','localhost','127.0.0.1'].includes(location.hostname))navigator.serviceWorker.register('./sw.js').catch(()=>{});
